# -*- coding: utf-8 -*-
"""AUTO-GENERATED by tools/gen_agent.py from endpoint/ - do not edit by hand.

Carries the PC agent so Network Doctor can PUBLISH the newest version to the IT share
(<endpoint_dir>/agent-dist/), from where every PC self-updates. Regenerate after editing the
endpoint files:  python3 tools/gen_agent.py  (a test asserts this file stays in sync)."""
import os

AGENT_VERSION = '1.4.0'

FILES = {
    'networkdoctor-agent.ps1': '# Network Doctor - one PC agent. Users click one button ("Fix my PC"); everything else runs in the background.\n#   -Mode fix         : clean the PC + send fresh details, connections and resource use to Network Doctor now\n#   -Mode background  : (runs at logon) watch USB drives and, every minute, which app uses the network + CPU/RAM\n#   -Mode recorder    : (only on PCs IT made "recorders") save the router\'s traffic data + DNS log while the\n#                       Network Doctor PC is off, and copy it to the share when the share is back\n# It sends only to the shared folder on the IT PC. It never reads a file\'s contents and never uses the internet.\nparam([ValidateSet("fix", "background", "recorder")] [string]$Mode = "fix")\n\n$AgentVersion = "1.4.0"    # the publisher bumps this; every PC silently self-updates to the newest in the share (~2 min)\n\n# ===== IT PC\'s shared folder (read by Network Doctor). Set once at install in central.txt; the line below is\n#       only the fallback when that file is missing, so a self-update never resets your real share. =====\n$cfgFile   = Join-Path $env:ProgramData "NetworkDoctor\\central.txt"\n$Central   = "\\\\RAKESH-IT\\LeakLog"\ntry { if (Test-Path $cfgFile) { $c = (Get-Content -LiteralPath $cfgFile -TotalCount 1).Trim(); if ($c) { $Central = $c } } } catch {}\n$MinCopyKB = 1\n# ====================================================================================\n\n$ErrorActionPreference = "SilentlyContinue"\n$ProgressPreference    = "SilentlyContinue"\n$pc    = $env:COMPUTERNAME\n$user  = $env:USERNAME\n$local = Join-Path $env:ProgramData "NetworkDoctor\\agent"\nNew-Item -ItemType Directory -Force -Path $local | Out-Null\n$month = Get-Date -f yyyyMM\nfunction Dirs { @($local, $Central) | Where-Object { $_ } }\nfunction Append($name, $header, $line) {\n    foreach ($d in Dirs) {\n        $p = Join-Path $d $name\n        if (-not (Test-Path $p)) { $header | Out-File -FilePath $p -Encoding utf8 }\n        $line | Out-File -FilePath $p -Encoding utf8 -Append\n    }\n}\nfunction Csv($v) { \'"\' + ("$v" -replace \'"\', \'""\') + \'"\' }\n\n# ---------- PC details + resources (JSON that Network Doctor reads straight into its inventory) ----------\nfunction Send-Details {\n    $cs   = Get-CimInstance Win32_ComputerSystem\n    $osi  = Get-CimInstance Win32_OperatingSystem\n    $bios = Get-CimInstance Win32_BIOS\n    $cpu  = Get-CimInstance Win32_Processor | Select-Object -First 1\n    $disk = Get-CimInstance Win32_LogicalDisk -Filter "DeviceID=\'C:\'"\n    $ads = foreach ($a in @(Get-NetAdapter -Physical)) {\n        [pscustomobject]@{ name = $a.Name; desc = $a.InterfaceDescription; mac = $a.MacAddress;\n            permanent = $a.PermanentAddress; status = [string]$a.Status;\n            wifi = [bool]($a.MediaType -match \'802\\.11\'); speed = [string]$a.LinkSpeed;\n            bps = [int64]$a.ReceiveLinkSpeed; duplex = $a.FullDuplex;\n            errors = [int64]((Get-NetAdapterStatistics -Name $a.Name).ReceivedPacketErrors);\n            ip = ((Get-NetIPAddress -InterfaceIndex $a.ifIndex -AddressFamily IPv4).IPAddress -join \',\') }\n    }\n    $cpuPct = [math]::Round((Get-CimInstance Win32_Processor | Measure-Object -Property LoadPercentage -Average).Average)\n    $memPct = if ($osi.TotalVisibleMemorySize) {\n        [math]::Round(100 * ($osi.TotalVisibleMemorySize - $osi.FreePhysicalMemory) / $osi.TotalVisibleMemorySize) }\n    $top = @(Get-Process | Group-Object ProcessName | ForEach-Object {\n        [pscustomobject]@{ name = $_.Name; mb = [math]::Round((($_.Group | Measure-Object WorkingSet64 -Sum).Sum)/1MB) }\n    } | Sort-Object mb -Descending | Select-Object -First 8)\n    $av = (@(Get-CimInstance -Namespace root/SecurityCenter2 -ClassName AntiVirusProduct) | ForEach-Object { $_.displayName }) -join \'; \'\n    $prn = (@(Get-CimInstance Win32_Printer | Where-Object { $_.Name -notmatch \'PDF|XPS|OneNote|Fax\' }) | ForEach-Object { $_.Name }) -join \'; \'\n    $hw = @{ maker=[string]$cs.Manufacturer; model=[string]$cs.Model; serial=[string]$bios.SerialNumber;\n             cpu=[string]$cpu.Name; ram_gb=[math]::Round(([double]$cs.TotalPhysicalMemory)/1GB,1);\n             disk_gb=[math]::Round(([double]$disk.Size)/1GB); disk_free_gb=[math]::Round(([double]$disk.FreeSpace)/1GB);\n             os_name=[string]$osi.Caption; os_version=[string]$osi.Version; last_boot=[string]$osi.LastBootUpTime;\n             logged_on=[string]$cs.UserName; antivirus=$av; printers=$prn;\n             cpu_load=$cpuPct; mem_used_pct=$memPct; top_procs=$top }\n    $body = @{ hostname=$pc; user=$user; os=[string]$osi.Caption; hw=$hw; adapters=@($ads);\n               time=(Get-Date).ToString("yyyy-MM-dd HH:mm:ss"); actions=@(\'PC agent report\') } | ConvertTo-Json -Depth 5\n    foreach ($d in Dirs) { $body | Out-File -FilePath (Join-Path $d "pc-$pc.json") -Encoding utf8 -Force }\n}\n\n# ---------- which app uses the network right now (process <-> remote address) ----------\nfunction Send-Connections {\n    $procs = @{}; Get-Process | ForEach-Object { $procs[$_.Id] = $_.ProcessName }\n    $seen = @{}\n    foreach ($c in @(Get-NetTCPConnection -State Established -ErrorAction SilentlyContinue)) {\n        $r = $c.RemoteAddress\n        if ($r -in @(\'127.0.0.1\',\'::1\',\'0.0.0.0\',\'::\') -or $r -like \'192.168.*\' -or $r -like \'10.*\' -or\n            $r -like \'172.1[6-9].*\' -or $r -like \'172.2*\' -or $r -like \'172.3[01].*\' -or $r -like \'fe80*\') { continue }\n        $name = $procs[[int]$c.OwningProcess]; if (-not $name) { continue }\n        $k = "$name|$r|$($c.RemotePort)"\n        if ($seen[$k]) { continue }; $seen[$k] = $true\n        Append "conn-$pc-$month.csv" "time,pc,user,process,local_ip,remote_ip,remote_port" `\n            (((Get-Date).ToString("yyyy-MM-dd HH:mm:ss")), $pc, $user, (Csv $name), $c.LocalAddress, $r, $c.RemotePort -join ",")\n    }\n}\n\nfunction Log-Usb($event, $detail, $drive, $kb) {\n    Append "leak-$pc-$month.csv" "time,pc,user,event,detail,drive,size_kb" `\n        (((Get-Date).ToString("yyyy-MM-dd HH:mm:ss")), $pc, $user, $event, (Csv $detail), $drive, [int]$kb -join ",")\n}\n\n# Is someone guessing this PC\'s password? Reads the Security log for failed logons (Event ID 4625) in the last\n# few minutes and reports them grouped by account + where they came from (source IP / computer). Network Doctor\n# raises a brute-force alert when the tries pile up. Reading the Security log needs admin - the agent runs as\n# SYSTEM, so it can. $mins is the look-back; the background loop calls it on the same cadence so nothing is missed.\nfunction Send-Auth($mins = 6) {\n    $since = (Get-Date).AddMinutes(-$mins)\n    $ev = @(Get-WinEvent -FilterHashtable @{LogName = \'Security\'; Id = 4625; StartTime = $since} `\n            -MaxEvents 1000 -ErrorAction SilentlyContinue)\n    if (-not $ev) { return }\n    $agg = @{}\n    foreach ($e in $ev) {\n        $d = @{}\n        try { foreach ($n in ([xml]$e.ToXml()).Event.EventData.Data) { $d[$n.Name] = [string]$n.\'#text\' } } catch { continue }\n        $acct = $d[\'TargetUserName\']; if (-not $acct) { $acct = \'?\' }\n        $ip = $d[\'IpAddress\']; $host2 = $d[\'WorkstationName\']\n        $from = if ($ip -and $ip -notin @(\'-\', \'::1\', \'127.0.0.1\')) { $ip } elseif ($host2) { $host2 } else { \'this PC / console\' }\n        $lt = $d[\'LogonType\']   # 10 = RDP (remote desktop), 3 = network share, 2 = at the keyboard\n        $kind = switch ($lt) { \'10\' { \'RDP\' } \'3\' { \'network\' } \'2\' { \'console\' } default { "type $lt" } }\n        $key = "$acct|$from|$kind"\n        if (-not $agg[$key]) { $agg[$key] = 0 }\n        $agg[$key]++\n    }\n    foreach ($k in $agg.Keys) {\n        $p = $k -split \'\\|\'\n        Append "auth-$pc-$month.csv" "time,pc,account,source,logon,fails" `\n            (((Get-Date).ToString("yyyy-MM-dd HH:mm:ss")), $pc, (Csv $p[0]), (Csv $p[1]), $p[2], $agg[$k] -join ",")\n    }\n}\nfunction Removable { Get-CimInstance Win32_LogicalDisk -Filter "DriveType=2" | ForEach-Object { $_.DeviceID } }\n\n\n# Shield against the "router drops for a few seconds" problem (ARP spoofing / a faked gateway): pin the router\'s\n# real MAC on THIS PC so it ignores fake ARP for the gateway. No router change, no IP/MAC binding, affects no one\n# else. Guarded: it pins ONLY when the internet is working right now, so it can never pin a spoofed MAC. A reboot\n# or "netsh interface ip delete neighbors" clears it. Needs admin.\nfunction Lock-Gateway {\n    $gw = (Get-NetRoute -DestinationPrefix \'0.0.0.0/0\' -ErrorAction SilentlyContinue |\n           Sort-Object RouteMetric | Select-Object -First 1).NextHop\n    if (-not $gw -or $gw -eq \'0.0.0.0\') { return }\n    if (-not (Test-Connection -Count 1 -Quiet -ErrorAction SilentlyContinue $gw)) { return }\n    # internet check: ICMP to 8.8.8.8 is blocked on many office networks, so fall back to a quick TCP test.\n    $okNet = (Test-Connection -Count 1 -Quiet -ErrorAction SilentlyContinue 8.8.8.8)\n    if (-not $okNet) {\n        foreach ($hp in @(@(\'8.8.8.8\', 53), @(\'1.1.1.1\', 443), @(\'8.8.4.4\', 443))) {\n            try { $c = New-Object Net.Sockets.TcpClient; $a = $c.BeginConnect($hp[0], $hp[1], $null, $null)\n                  if ($a.AsyncWaitHandle.WaitOne(1200) -and $c.Connected) { $okNet = $true; $c.Close(); break }\n                  $c.Close() } catch {}\n        }\n    }\n    if (-not $okNet) { Write-Host "   - Router shield skipped (internet not reachable right now)" -ForegroundColor DarkGray; return }\n    $n = Get-NetNeighbor -IPAddress $gw -ErrorAction SilentlyContinue |\n         Where-Object { $_.LinkLayerAddress -and $_.State -ne \'Unreachable\' } | Select-Object -First 1\n    if ($n -and $n.LinkLayerAddress) {\n        netsh interface ipv4 set neighbors $n.InterfaceIndex $gw $n.LinkLayerAddress store=active 2>$null | Out-Null\n        Write-Host "   - Router address locked ($gw = $($n.LinkLayerAddress)) - ignores fake ARP"\n    }\n}\n\n# ================================ FIX (the one button the user clicks) ================================\nif ($Mode -eq "fix") {\n    $me = [Security.Principal.WindowsIdentity]::GetCurrent()\n    $amAdmin = ([Security.Principal.WindowsPrincipal]$me).IsInRole([Security.Principal.WindowsBuiltinRole]::Administrator)\n    $asSystem = $me.IsSystem        # launched by the scheduled task: full rights, no password, runs hidden\n    # If a person ran this directly without rights (not through the "Fix my PC" task), lift it once.\n    if (-not $amAdmin -and -not $asSystem) {\n        try {\n            Start-Process powershell -Verb RunAs -ArgumentList @(\n                "-NoProfile", "-ExecutionPolicy", "Bypass", "-File", "`"$PSCommandPath`"", "-Mode", "fix")\n            return\n        } catch {\n            Write-Host "  (Running without administrator - some deep steps will be skipped.)" -ForegroundColor DarkGray\n        }\n    }\n    $host.UI.RawUI.WindowTitle = "Fix my PC"\n    $before = (Get-PSDrive C).Free\n    # --- status file: the one reliable signal. Written as SYSTEM, read by fix-launch.cmd in the user\'s\n    #     session - so "Fix my PC" shows live progress and the result WITHOUT depending on msg.exe (which is\n    #     missing on Windows Home) or on a visible window (the task runs hidden). "done" vs "stuck" is never\n    #     a guess again: the file says exactly which step is running, or DONE / FAILED.\n    $StatusDir = Join-Path $env:ProgramData "NetworkDoctor"\n    try { if (-not (Test-Path $StatusDir)) { New-Item -ItemType Directory -Path $StatusDir -Force | Out-Null } } catch {}\n    $StatusFile = Join-Path $StatusDir "fix-status.txt"\n    function Set-Status($line) { try { Set-Content -LiteralPath $StatusFile -Value $line -Encoding ASCII -ErrorAction SilentlyContinue } catch {} }\n    Set-Status "RUNNING|starting"\n    Write-Host "`n  Fixing and cleaning this PC... please wait.`n" -ForegroundColor Cyan\n    function Purge($path, $label) {\n        if (-not (Test-Path $path)) { return }\n        Write-Host "   - $label"; Set-Status "RUNNING|$label"\n        Get-ChildItem $path -Recurse -Force -ErrorAction SilentlyContinue |\n            Where-Object { -not $_.PSIsContainer -and $_.LastWriteTime -lt (Get-Date).AddHours(-1) } |\n            Remove-Item -Force -ErrorAction SilentlyContinue\n    }\n    try {\n        # Clean every user\'s junk (works whether started as SYSTEM by the task, or by an admin). Never real files.\n        Purge "C:\\Users\\*\\AppData\\Local\\Temp" "Temporary files"\n        Purge "C:\\Users\\*\\AppData\\Local\\Microsoft\\Windows\\INetCache" "Internet cache"\n        Purge "C:\\Users\\*\\AppData\\Local\\CrashDumps" "Crash dumps"\n        Purge "C:\\Users\\*\\AppData\\Local\\Google\\Chrome\\User Data\\*\\Cache" "Chrome cache"\n        Purge "C:\\Users\\*\\AppData\\Local\\Microsoft\\Edge\\User Data\\*\\Cache" "Edge cache"\n        Purge "$env:WINDIR\\Temp" "Windows temp"\n        Set-Status "RUNNING|Windows Update leftovers"\n        Stop-Service wuauserv -Force; Purge "$env:WINDIR\\SoftwareDistribution\\Download" "Windows Update leftovers"; Start-Service wuauserv\n        Write-Host "   - Prefetch (Windows rebuilds it)"; Set-Status "RUNNING|Prefetch"\n        Remove-Item "$env:WINDIR\\Prefetch\\*" -Force -ErrorAction SilentlyContinue\n        Delete-DeliveryOptimizationCache -Force -ErrorAction SilentlyContinue | Out-Null\n        Write-Host "   - Windows disk cleanup (old updates, logs)"; Set-Status "RUNNING|Windows disk cleanup"\n        Dism.exe /Online /Cleanup-Image /StartComponentCleanup /Quiet | Out-Null   # reclaims WinSxS space, safe\n        Write-Host "   - Checking Windows health"; Set-Status "RUNNING|Checking Windows health"\n        if ("$(Dism.exe /Online /Cleanup-Image /CheckHealth)" -match \'repairable\') {\n            Write-Host "     Repairable damage found - repairing Windows (several minutes)..." -ForegroundColor Yellow\n            Set-Status "RUNNING|Repairing Windows (this can take 15-30 min)"\n            Dism.exe /Online /Cleanup-Image /RestoreHealth /Quiet | Out-Null\n            sfc /scannow | Out-Null\n            Write-Host "     Windows repair done."\n        } else { Write-Host "     Windows is healthy." }\n        Lock-Gateway                                                               # router-drop shield (needs rights)\n        Write-Host "   - Recycle Bin"; Set-Status "RUNNING|Emptying Recycle Bin"; Clear-RecycleBin -Force -ErrorAction SilentlyContinue\n        Write-Host "   - Flushing DNS"; Set-Status "RUNNING|Flushing DNS"; ipconfig /flushdns | Out-Null\n        Write-Host "   - Updating details"; Set-Status "RUNNING|Updating details"; Send-Details; Send-Connections\n        if (-not $asSystem) {                                                      # restarting Explorer only makes\n            Write-Host "   - Restarting Explorer"                                  # sense in the user\'s own session\n            Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue; Start-Sleep 2\n            if (-not (Get-Process explorer -ErrorAction SilentlyContinue)) { Start-Process explorer }\n        }\n        $freed = [math]::Round(((Get-PSDrive C).Free - $before)/1MB); if ($freed -lt 0) { $freed = 0 }\n        $msg = "PC cleaned and optimised. Freed about $freed MB. If it is still slow, tell IT."\n        Write-Host "`n  $msg`n" -ForegroundColor Green\n        Set-Status "DONE|$freed|$(Get-Date -Format \'yyyy-MM-dd HH:mm\')"\n        if ($asSystem) { try { & msg.exe * /TIME:30 $msg } catch {} }             # bonus popup where msg.exe exists\n    } catch {\n        Set-Status "FAILED|$($_.Exception.Message)"\n        Write-Host "  Problem while fixing: $($_.Exception.Message)" -ForegroundColor Red\n    }\n    Start-Sleep 4\n    return\n}\n\n# ================================ SELF-UPDATE (silent, from the IT share - no internet, no per-PC reinstall) ===\n$DST = Split-Path $local    # %ProgramData%\\NetworkDoctor  (where the installed agent + launcher live)\nfunction Update-Self {\n    # Pull a newer agent that Network Doctor published to <share>\\agent-dist\\. Returns $true if it updated the\n    # local files (the caller then relaunches so the new code runs). Never throws - an update must never break\n    # the agent that is already working.\n    try {\n        $dist = Join-Path $Central "agent-dist"\n        $verFile = Join-Path $dist "version.txt"\n        if (-not (Test-Path $verFile)) { return $false }\n        $remote = (Get-Content -LiteralPath $verFile -TotalCount 1).Trim()\n        if (-not $remote) { return $false }\n        if ([version]$remote -le [version]$AgentVersion) { return $false }\n        $src = Join-Path $dist "networkdoctor-agent.ps1"\n        if (-not (Test-Path $src)) { return $false }\n        Copy-Item -LiteralPath $src -Destination (Join-Path $DST "networkdoctor-agent.ps1") -Force\n        $fl = Join-Path $dist "fix-launch.cmd"\n        if (Test-Path $fl) { Copy-Item -LiteralPath $fl -Destination (Join-Path $DST "fix-launch.cmd") -Force }\n        return $true\n    } catch { return $false }\n}\n\n# ================================ TAMPER PROTECTION + IT-CONTROLLED UNINSTALL ================================\n# The agent stays installed and running until IT turns it off from Network Doctor. It will NOT uninstall on a\n# user\'s command - only when a signed "allow removal" token for THIS PC (or all PCs) appears in the IT share.\n# Between those, a watchdog re-creates the tasks and re-copies the files if a user deletes them.\n$BgName    = "NetworkDoctor Agent"\n$BootName  = "NetworkDoctor Agent Boot"\n$WdName     = "NetworkDoctor Agent Watchdog"\n$FixName   = "NetworkDoctor Fix"\n$AgentPath = Join-Path $DST "networkdoctor-agent.ps1"\n\nfunction Agent-RunLine($mode) {\n    return "powershell -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$AgentPath`" -Mode $mode"\n}\n\n# Re-create anything a user removed. Runs as SYSTEM, so a standard user cannot stop it from coming back.\nfunction Self-Heal {\n    try {\n        # the background task(s) must exist\n        if (-not (schtasks /Query /TN $BgName 2>$null)) {\n            schtasks /Create /TN $BgName /TR (Agent-RunLine "background") /RU SYSTEM /RL HIGHEST /F /SC ONLOGON 2>$null | Out-Null\n        }\n        if (-not (schtasks /Query /TN $BootName 2>$null)) {\n            schtasks /Create /TN $BootName /TR (Agent-RunLine "background") /RU SYSTEM /RL HIGHEST /F /SC ONSTART 2>$null | Out-Null\n        }\n        if (-not (schtasks /Query /TN $WdName 2>$null)) {\n            $wd = Join-Path $DST "watchdog.cmd"\n            if (Test-Path $wd) {\n                schtasks /Create /TN $WdName /TR ("cmd /c `"$wd`"") /RU SYSTEM /RL HIGHEST /F /SC MINUTE /MO 10 2>$null | Out-Null\n            }\n        }\n        # the folder lock-down (standard users: read+execute only)\n        icacls $DST /inheritance:r 2>$null | Out-Null\n        icacls $DST /grant:r "SYSTEM:(OI)(CI)F" "Administrators:(OI)(CI)F" "Users:(OI)(CI)RX" 2>$null | Out-Null\n    } catch {}\n}\n\n# Does the IT share hold a valid "allow removal" token for this PC? The token is a file IT writes from Network\n# Doctor; it names either this PC or ALL, and carries the shared secret from central.txt line 2 (so a user who\n# can see the share still can\'t forge it without the secret). Returns $true only on a genuine IT token.\nfunction Uninstall-Allowed {\n    try {\n        $tokDir = Join-Path $Central "agent-remove"\n        if (-not (Test-Path $tokDir)) { return $false }\n        # the shared secret (optional 2nd line of central.txt). If none set, any token in the IT share counts -\n        # the share itself is the IT PC\'s, which users can read but the token is still an explicit IT action.\n        $secret = ""\n        try { $cl = Get-Content -LiteralPath $cfgFile -TotalCount 2; if ($cl.Count -ge 2) { $secret = ($cl[1]).Trim() } } catch {}\n        foreach ($nm in @("$pc.txt", "ALL.txt")) {\n            $f = Join-Path $tokDir $nm\n            if (Test-Path $f) {\n                if (-not $secret) { return $true }\n                $body = ""\n                try { $body = (Get-Content -LiteralPath $f -Raw).Trim() } catch {}\n                if ($body -eq $secret) { return $true }\n            }\n        }\n    } catch {}\n    return $false\n}\n\n# Clean, complete self-removal - ONLY ever called after Uninstall-Allowed. Removes tasks, the lock-down, and the\n# files, then exits. (It cannot delete the running .ps1 it is reading, so it schedules a final cleanup.)\nfunction Do-Uninstall {\n    try {\n        Log-Usb "AGENT_REMOVE" "IT allowed removal - agent uninstalling on this PC" "" 0\n        Remove-Item -LiteralPath (Join-Path $DST "recorder.txt") -Force -ErrorAction SilentlyContinue   # recorder stops\n        netsh advfirewall firewall delete rule name="NetworkDoctor Recorder" 2>$null | Out-Null\n        foreach ($t in @($BgName, $BootName, $WdName, $FixName)) { schtasks /Delete /TN $t /F 2>$null | Out-Null }\n        # give the folder back to normal, then remove everything on next boot via a one-shot cleanup task\n        icacls $DST /reset /T 2>$null | Out-Null\n        $clean = "timeout /t 3 >nul & rd /s /q `"$DST`" & schtasks /Delete /TN `"NetworkDoctor Cleanup`" /F >nul 2>&1"\n        $cf = Join-Path $env:TEMP "nd-clean.cmd"\n        Set-Content -LiteralPath $cf -Value $clean -Encoding ASCII\n        schtasks /Create /TN "NetworkDoctor Cleanup" /TR ("cmd /c `"$cf`"") /RU SYSTEM /RL HIGHEST /F /SC ONCE /ST 00:00 2>$null | Out-Null\n        schtasks /Run /TN "NetworkDoctor Cleanup" 2>$null | Out-Null\n    } catch {}\n    exit\n}\n\n# ================================ RECORDER (only on PCs that IT made recorders in Network Doctor) ============\n# The router sends its traffic data only to the Network Doctor PC, so hours when that PC is off were lost. On a\n# recorder PC the router also sends a COPY here (UDP 2056 flows, UDP 5516 DNS log). This only writes what arrives,\n# as it arrives, into 10-minute files on this PC, and copies each finished file to <share>\\collect\\<PC>\\ whenever\n# the share is reachable. Network Doctor imports them when it is on again (never counting a second twice).\n# It never sends anything anywhere else and never changes the router.\n$RecDir    = Join-Path $DST "collect"\n$RecSent   = Join-Path $RecDir "sent"\n$RecFlag   = Join-Path $DST "recorder.txt"\n$RecBeat   = Join-Path $DST "recorder.beat"\n$RecRule   = "NetworkDoctor Recorder"\n$RecFlowPort = 2056\n$RecDnsPort  = 5516\n$RecKeepDays = 14\n$RecMaxBytes = 2GB\n\nfunction Recorder-Secret {\n    try { $cl = Get-Content -LiteralPath $cfgFile -TotalCount 2; if ($cl.Count -ge 2) { return ($cl[1]).Trim() } } catch {}\n    return ""\n}\n\n# IT switches a PC on with <share>\\collect\\on\\<PC>.txt holding the secret (central.txt line 2). The answer is\n# remembered on this PC, so it keeps recording while the share (the IT PC) is off.\nfunction Recorder-Wanted {\n    try {\n        if (Test-Path -LiteralPath $Central) {\n            $f = Join-Path $Central ("collect\\on\\" + $pc + ".txt")\n            $ok = $false\n            if (Test-Path -LiteralPath $f) {\n                $secret = Recorder-Secret\n                $body = ""\n                try { $body = (Get-Content -LiteralPath $f -Raw).Trim() } catch {}\n                $ok = (-not $secret) -or ($body -eq $secret)\n            }\n            if ($ok) { if (-not (Test-Path -LiteralPath $RecFlag)) { Set-Content -LiteralPath $RecFlag -Value "on" -Encoding ASCII } }\n            elseif (Test-Path -LiteralPath $RecFlag) { Remove-Item -LiteralPath $RecFlag -Force }\n        }\n    } catch {}\n    return (Test-Path -LiteralPath $RecFlag)\n}\n\nfunction Recorder-Running {\n    try {\n        if (-not (Test-Path -LiteralPath $RecBeat)) { return $false }\n        return (((Get-Date) - (Get-Item -LiteralPath $RecBeat).LastWriteTime).TotalSeconds -lt 120)\n    } catch { return $false }\n}\n\nfunction Start-Recorder {\n    Start-Process powershell -WindowStyle Hidden -ArgumentList \'-NoProfile\',\'-WindowStyle\',\'Hidden\',\'-ExecutionPolicy\',\'Bypass\',\'-File\',(Join-Path $DST \'networkdoctor-agent.ps1\'),\'-Mode\',\'recorder\'\n}\n\nif ($Mode -eq "recorder") {\n    $rmtx = New-Object System.Threading.Mutex($false, "Global\\NetworkDoctorRecorder")\n    if (-not $rmtx.WaitOne(0)) { exit }\n    if (-not (Test-Path -LiteralPath $RecFlag)) { exit }\n    New-Item -ItemType Directory -Force -Path $RecDir, $RecSent | Out-Null\n    # open the two ports for the local network only (the router is on it); removed again when recording stops\n    netsh advfirewall firewall delete rule name="$RecRule" 2>$null | Out-Null\n    netsh advfirewall firewall add rule name="$RecRule" dir=in action=allow protocol=UDP localport="$RecFlowPort,$RecDnsPort" remoteip=localsubnet 2>$null | Out-Null\n    $uf = $null; $ud = $null\n    try {\n        $uf = New-Object System.Net.Sockets.UdpClient $RecFlowPort\n        $uf.Client.ReceiveBufferSize = 4MB\n        $ud = New-Object System.Net.Sockets.UdpClient $RecDnsPort\n        $ud.Client.ReceiveBufferSize = 1MB\n    } catch {\n        Set-Content -LiteralPath (Join-Path $RecDir "error.txt") -Value ("ports busy: " + $_.Exception.Message) -Encoding ASCII\n        exit\n    }\n    $chunk = ""; $fw = $null; $bw = $null; $dw = $null\n    $packets = 0; $lines = 0; $lastPkt = 0; $lastSync = [DateTime]::MinValue; $lastArp = [DateTime]::MinValue\n    $shareNext = [DateTime]::MinValue\n    $utf8 = New-Object System.Text.UTF8Encoding($false)\n    $epoch = [DateTime]::new(1970, 1, 1, 0, 0, 0, [DateTimeKind]::Utc)\n\n    function Rec-Close {\n        foreach ($w in @($bw, $dw)) { if ($w) { try { $w.Flush(); $w.Close() } catch {} } }\n        if ($fw) { try { $fw.Close() } catch {} }\n        $script:bw = $null; $script:dw = $null; $script:fw = $null\n        Get-ChildItem -LiteralPath $RecDir -File | Where-Object { $_.Length -eq 0 -and $_.Name -match \'^(flow|dns)-\' } |\n            ForEach-Object { Remove-Item -LiteralPath $_.FullName -Force }\n    }\n    function Rec-Open($c) {\n        $script:fw = [IO.File]::Open((Join-Path $RecDir "flow-$c.ndf"), \'Append\', \'Write\', \'Read\')\n        $script:bw = New-Object IO.BinaryWriter($script:fw)\n        $script:dw = New-Object IO.StreamWriter((Join-Path $RecDir "dns-$c.txt"), $true, $utf8)\n    }\n    # copy every finished file to the share (via .tmp, so Network Doctor never reads half a file), then keep\n    # the local copy in sent\\ for a while. Old files go so the disk never fills up.\n    function Rec-Sync {\n        $pending = 0\n        $files = Get-ChildItem -LiteralPath $RecDir -File | Where-Object { $_.Name -match \'^(flow|dns)-(\\d{8}-\\d{4})\\.\' -and $Matches[2] -ne $chunk }\n        # the IT PC off: an unreachable share can take many seconds to answer, so try it every 5 minutes only\n        $shareOk = $false\n        if ((Get-Date) -ge $script:shareNext) {\n            $shareOk = Test-Path -LiteralPath $Central\n            if (-not $shareOk) { $script:shareNext = (Get-Date).AddMinutes(5) }\n        }\n        $dst = Join-Path $Central ("collect\\" + $pc)\n        if ($shareOk) { try { New-Item -ItemType Directory -Force -Path $dst | Out-Null } catch { $shareOk = $false } }\n        foreach ($f in $files) {\n            $done = $false\n            if ($shareOk) {\n                try {\n                    $t = Join-Path $dst $f.Name\n                    Copy-Item -LiteralPath $f.FullName -Destination ($t + ".tmp") -Force\n                    if ((Get-Item -LiteralPath ($t + ".tmp")).Length -eq $f.Length) {\n                        Move-Item -LiteralPath ($t + ".tmp") -Destination $t -Force\n                        Move-Item -LiteralPath $f.FullName -Destination (Join-Path $RecSent $f.Name) -Force\n                        $done = $true\n                    }\n                } catch {}\n            }\n            if (-not $done) { $pending++ }\n        }\n        if ($shareOk) {\n            Get-ChildItem -LiteralPath $RecDir -File -Filter "arp-*.csv" | ForEach-Object {\n                try { Copy-Item -LiteralPath $_.FullName -Destination (Join-Path $dst $_.Name) -Force } catch {}\n            }\n        }\n        # housekeeping: sent files after $RecKeepDays, anything after 30 days, oldest first above $RecMaxBytes\n        $cut = (Get-Date).AddDays(-$RecKeepDays)\n        Get-ChildItem -LiteralPath $RecSent -File | Where-Object { $_.LastWriteTime -lt $cut } | Remove-Item -Force\n        Get-ChildItem -LiteralPath $RecDir -File | Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-30) } | Remove-Item -Force\n        $all = @(Get-ChildItem -LiteralPath $RecDir -File -Recurse | Sort-Object LastWriteTime)\n        $sum = ($all | Measure-Object Length -Sum).Sum\n        foreach ($f in $all) { if ($sum -le $RecMaxBytes) { break }; if ($f.Name -match $chunk) { continue }; $sum -= $f.Length; Remove-Item -LiteralPath $f.FullName -Force }\n        if ($shareOk) {\n            $ip = ""\n            try { $ip = (Get-NetIPAddress -AddressFamily IPv4 | Where-Object { $_.IPAddress -match \'^(192\\.168|10\\.|172\\.)\' } | Select-Object -First 1).IPAddress } catch {}\n            $now = [long]([DateTime]::UtcNow - $epoch).TotalMilliseconds\n            $st = "version=$AgentVersion`r`nip=$ip`r`nupdated=$now`r`nlast_packet=$lastPkt`r`npackets=$packets`r`ndns_lines=$lines`r`npending=$pending`r`n"\n            try { [IO.File]::WriteAllText((Join-Path $dst "status.txt"), $st, $utf8) } catch {}\n        }\n    }\n    # which MAC had which IP (from this PC\'s neighbour table), so the history stays with the device\n    function Rec-Arp {\n        try {\n            $now = [long]([DateTime]::UtcNow - $epoch).TotalMilliseconds\n            $f = Join-Path $RecDir ("arp-" + [DateTime]::UtcNow.ToString("yyyyMMdd") + ".csv")\n            $rows = Get-NetNeighbor -AddressFamily IPv4 | Where-Object { $_.LinkLayerAddress -and $_.LinkLayerAddress -ne "00-00-00-00-00-00" -and $_.LinkLayerAddress -notmatch \'^(FF-FF|01-00)\' -and $_.IPAddress -match \'^(192\\.168|10\\.|172\\.)\' }\n            $out = foreach ($r in $rows) { "$now,$($r.IPAddress),$($r.LinkLayerAddress)" }\n            if ($out) { [IO.File]::AppendAllText($f, (($out -join "`r`n") + "`r`n"), $utf8) }\n        } catch {}\n    }\n\n    $ep = New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Any, 0)\n    while ($true) {\n        $u = [DateTime]::UtcNow\n        $c = $u.ToString("yyyyMMdd-HH") + ([int][math]::Floor($u.Minute / 10) * 10).ToString("00")\n        if ($c -ne $chunk) { Rec-Close; $chunk = $c; Rec-Open $c }\n        $ms = [long]($u - $epoch).TotalMilliseconds\n        try {\n            while ($uf.Available -gt 0) {\n                $b = $uf.Receive([ref]$ep)\n                $bw.Write([long]$ms); $bw.Write($ep.Address.GetAddressBytes(), 0, 4); $bw.Write([uint16]$b.Length); $bw.Write($b)\n                $packets++; $lastPkt = $ms\n            }\n            while ($ud.Available -gt 0) {\n                $b = $ud.Receive([ref]$ep)\n                $txt = $utf8.GetString($b) -replace "[`t`r`n]", " "\n                $dw.WriteLine("$ms`t$($ep.Address)`t$txt")\n                $lines++\n            }\n        } catch {}\n        if (($u - $lastSync).TotalSeconds -ge 60) {\n            $lastSync = $u\n            try { $bw.Flush(); $dw.Flush() } catch {}\n            try { Set-Content -LiteralPath $RecBeat -Value $ms -Encoding ASCII } catch {}\n            if (($u - $lastArp).TotalMinutes -ge 5) { $lastArp = $u; Rec-Arp }\n            Rec-Sync\n            if (-not (Test-Path -LiteralPath $RecFlag)) { break }     # IT stopped recording on this PC\n        }\n        Start-Sleep -Milliseconds 200\n    }\n    Rec-Close; $chunk = ""; $shareNext = [DateTime]::MinValue; Rec-Sync\n    try { $uf.Close(); $ud.Close() } catch {}\n    netsh advfirewall firewall delete rule name="$RecRule" 2>$null | Out-Null\n    Remove-Item -LiteralPath $RecBeat -Force -ErrorAction SilentlyContinue\n    exit\n}\n\n# ================================ BACKGROUND (starts at logon, no window) ================================\n# One background instance only. A self-update relaunches a fresh copy; this mutex stops duplicates stacking up.\n$mtx = New-Object System.Threading.Mutex($false, "Global\\NetworkDoctorAgentBG")\nif (-not $mtx.WaitOne(0)) { exit }\nif (Update-Self) {\n    $mtx.ReleaseMutex()\n    Start-Process powershell -ArgumentList \'-NoProfile\',\'-WindowStyle\',\'Hidden\',\'-ExecutionPolicy\',\'Bypass\',\'-File\',(Join-Path $DST \'networkdoctor-agent.ps1\'),\'-Mode\',\'background\'\n    exit\n}\nLog-Usb "AGENT_START" "PC agent v$AgentVersion started" "" 0\nSend-Details\nLock-Gateway        # shield the router\'s address at every logon (background runs as SYSTEM, so it has the rights)\nSend-Auth 60        # catch password-guessing that happened in the last hour before the agent started\nif ((Recorder-Wanted) -and -not (Recorder-Running)) { Start-Recorder }   # a recorder starts with the PC, no logon needed\n$watchers = @{}\nfunction Watch($drive) {\n    if ($watchers.ContainsKey($drive)) { return }\n    $w = New-Object IO.FileSystemWatcher ($drive + "\\"), "*.*"; $w.IncludeSubdirectories = $true; $w.EnableRaisingEvents = $true\n    $act = {\n        $p = $Event.SourceEventArgs.FullPath; Start-Sleep -Milliseconds 400\n        $kb = 0; try { $kb = [math]::Round((Get-Item -LiteralPath $p).Length/1KB) } catch {}\n        if ($kb -ge $using:MinCopyKB) {\n            & $using:LogUsb "COPY_TO_USB" $p ($p.Substring(0,2)) $kb\n        }\n    }\n    Register-ObjectEvent $w Created -Action $act | Out-Null\n    Register-ObjectEvent $w Renamed -Action $act | Out-Null\n    $watchers[$drive] = $w\n}\n$LogUsb = ${function:Log-Usb}\nforeach ($d in Removable) { Watch $d; Log-Usb "USB_PRESENT" "Drive $d already connected" $d 0 }\n$known = @(Removable); $tick = 0\nwhile ($true) {\n    Start-Sleep -Seconds 3\n    $now = @(Removable)\n    foreach ($d in $now)   { if ($known -notcontains $d) { Log-Usb "USB_IN"  "Removable drive connected" $d 0; Watch $d } }\n    foreach ($d in $known) { if ($now   -notcontains $d) { Log-Usb "USB_OUT" "Removable drive removed"   $d 0 } }\n    $known = $now\n    $tick++\n    if ($tick % 20 -eq 0) {                               # every ~60s: tamper check\n        if (Uninstall-Allowed) { Do-Uninstall }          # IT turned it off from Network Doctor -> remove cleanly\n        else { Self-Heal }                               # otherwise make sure nothing was removed by a user\n    }\n    if ($tick % 20 -eq 0) { Send-Connections }           # every ~60s: which app is using the network\n    if ($tick % 20 -eq 0) {                               # every ~60s: recorder on / off as IT set it\n        if ((Recorder-Wanted) -and -not (Recorder-Running)) { Start-Recorder }\n    }\n    if ($tick % 100 -eq 0) { Send-Auth 6 }               # every ~5 min: failed-login (brute-force) check\n    if ($tick % 40 -eq 0) {                                # every ~2 min: pick up an update the app published\n        if (Update-Self) {                                 # (a published version bump reaches every PC in ~2 min,\n            $mtx.ReleaseMutex()                            #  no per-PC visit, no remote command, no credentials)\n            Start-Process powershell -ArgumentList \'-NoProfile\',\'-WindowStyle\',\'Hidden\',\'-ExecutionPolicy\',\'Bypass\',\'-File\',(Join-Path $DST \'networkdoctor-agent.ps1\'),\'-Mode\',\'background\'\n            exit\n        }\n    }\n    if ($tick % 600 -eq 0) { Send-Details; Lock-Gateway }  # every ~30 min: refresh details, re-pin router\n}\n',
    'fix-launch.cmd': '@echo off\nsetlocal EnableExtensions\ntitle Fix my PC\nset "ST=%ProgramData%\\NetworkDoctor\\fix-status.txt"\ndel "%ST%" >nul 2>&1\necho(\necho    Cleaning and optimising your PC... you can keep working.\necho    (A Windows repair, if needed, can take 15-30 minutes - that is normal.)\necho(\nschtasks /Run /TN "NetworkDoctor Fix" >nul 2>&1\nif errorlevel 1 (\n    echo    Could not start. Please tell IT.\n    echo(\n    pause\n    exit /b 1\n)\n\nset "LAST="\nset /a tries=0\n:loop\nset "LINE="\nif exist "%ST%" set /p LINE=<"%ST%"\nif not "%LINE%"=="%LAST%" (\n    for /f "tokens=1,2,3 delims=|" %%a in ("%LINE%") do (\n        if /I "%%a"=="DONE"   ( echo    Done^!  Freed about %%b MB.  & goto done )\n        if /I "%%a"=="FAILED" ( echo    Could not finish: %%b  -  please tell IT.  & goto done )\n        if /I "%%a"=="RUNNING" ( echo       - %%b )\n    )\n    set "LAST=%LINE%"\n)\nset /a tries+=1\nrem ~40 minutes max of waiting (480 x 5s), then let the user go - the task keeps running in the background\nif %tries% GEQ 480 (\n    echo(\n    echo    Still working in the background ^(Windows repair takes a while^). It is safe to close this window.\n    goto done\n)\ntimeout /t 5 >nul 2>&1\ngoto loop\n\n:done\necho(\npause\nexit /b 0\n',
}

def publish(endpoint_dir):
    """Write the embedded agent + a version.txt into <endpoint_dir>/agent-dist/ so every PC's agent self-updates
    to this version. Overwrites only when this version is newer or the files are missing/changed. Best-effort:
    returns the version written, or None if the folder is not writable. Never raises."""
    try:
        if not endpoint_dir:
            return None
        dist = os.path.join(endpoint_dir, "agent-dist")
        os.makedirs(dist, exist_ok=True)
        ver_path = os.path.join(dist, "version.txt")
        current = ""
        try:
            with open(ver_path, "r", encoding="utf-8") as f:
                current = f.read().strip()
        except OSError:
            current = ""
        if current and _ge(current, AGENT_VERSION):
            # a same-or-newer master is already there (another IT PC, or this version) - nothing to push
            return current
        for name, text in FILES.items():
            with open(os.path.join(dist, name), "w", encoding="utf-8", newline="") as f:
                f.write(text)
        with open(ver_path, "w", encoding="utf-8") as f:
            f.write(AGENT_VERSION)
        return AGENT_VERSION
    except Exception:
        return None


def _ge(a, b):
    """a >= b for dotted numeric versions, without packaging deps."""
    def t(v):
        out = []
        for p in str(v).split("."):
            try:
                out.append(int(p))
            except ValueError:
                out.append(0)
        return out
    return t(a) >= t(b)
